def isbn13_valid(s):
    if not isinstance(s, str):
        return False
    t = ''.join(ch for ch in s if ch != ' ' and ch != '-')
    if len(t) != 13:
        return False
    total = 0
    for i, ch in enumerate(t):
        if ch < '0' or ch > '9':
            return False
        total += (i % 2 == 0) * 1 * (ord(ch) - 48) + (i % 2 == 1) * 3 * (ord(ch) - 48)
    return total % 10 == 0
