def parse_ini(text):
    result = {}
    current = ''
    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        if line.startswith(';') or line.startswith('#'):
            continue
        if line.startswith('[') and line.endswith(']') and ']' not in line[1:-1]:
            name = line[1:-1].strip()
            current = name
            result.setdefault(current, {})
            continue
        if '=' in line:
            key, value = line.split('=', 1)
            key = key.strip()
            value = value.strip()
            if not key:
                raise ValueError('empty key in line: %r' % raw)
            result.setdefault(current, {})[key] = value
            continue
        raise ValueError('invalid line: %r' % raw)
    return result
